import{_ as a,o as r,c as e,a as o}from"./app.DkoUFz-u.js";const p=JSON.parse('{"title":"数据库层开发-高性能访问-数据分片-分片管理-分片监控 学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/sharding/management/monitoring.md","filePath":"data/performance/sharding/management/monitoring.md"}'),d={name:"data/performance/sharding/management/monitoring.md"};function n(s,t,i,l,h,g){return r(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据库层开发-高性能访问-数据分片-分片管理-分片监控-学习笔记" tabindex="-1">数据库层开发-高性能访问-数据分片-分片管理-分片监控 学习笔记 <a class="header-anchor" href="#数据库层开发-高性能访问-数据分片-分片管理-分片监控-学习笔记" aria-label="Permalink to &quot;数据库层开发-高性能访问-数据分片-分片管理-分片监控 学习笔记&quot;">​</a></h1><h2 id="一、概述-什么是分片监控" tabindex="-1">一、概述：什么是分片监控 <a class="header-anchor" href="#一、概述-什么是分片监控" aria-label="Permalink to &quot;一、概述：什么是分片监控&quot;">​</a></h2><h3 id="_1-1-定义" tabindex="-1">1.1 定义 <a class="header-anchor" href="#_1-1-定义" aria-label="Permalink to &quot;1.1 定义&quot;">​</a></h3><p><strong>分片监控（Sharding Monitoring）</strong> 是指在分库分表架构下，对分布式数据库集群中各个分片节点、路由中间件、数据分布状态以及业务访问情况进行全方位的指标采集、实时分析和异常告警的系统性运维活动。</p><h3 id="_1-2-为什么分片监控至关重要" tabindex="-1">1.2 为什么分片监控至关重要 <a class="header-anchor" href="#_1-2-为什么分片监控至关重要" aria-label="Permalink to &quot;1.2 为什么分片监控至关重要&quot;">​</a></h3><p>当一个分片集群扩展到上百个节点、承载数千个业务表、日吞吐量达到亿级时，传统的“人眼盯屏+手动操作”模式彻底失效。监控数据每分钟产生数万条时序指标，而分布式系统的故障传播链条比单机复杂得多——<strong>一个分片的慢查询可能引发全局连接池拥堵，一次网络抖动可能导致多个分片的数据同步滞后</strong>。</p><p><strong>分片监控的价值体现在三个层面</strong>：</p><table tabindex="0"><thead><tr><th>层面</th><th>解决的问题</th></tr></thead><tbody><tr><td><strong>可用性保障</strong></td><td>及时发现节点故障、连接池耗尽、磁盘爆满等致命问题</td></tr><tr><td><strong>性能优化</strong></td><td>定位慢SQL、热点分片、数据倾斜等性能瓶颈</td></tr><tr><td><strong>容量规划</strong></td><td>回答“何时需要增加分片”“哪个分片最先达到容量上限”等问题</td></tr></tbody></table><p>没有监控的分片集群，就像在黑暗中驾驶——你不知道速度、不知道油量、更不知道哪个轮胎即将爆裂。</p><h2 id="二、分片监控体系全景" tabindex="-1">二、分片监控体系全景 <a class="header-anchor" href="#二、分片监控体系全景" aria-label="Permalink to &quot;二、分片监控体系全景&quot;">​</a></h2><h3 id="_2-1-三层监控指标体系" tabindex="-1">2.1 三层监控指标体系 <a class="header-anchor" href="#_2-1-三层监控指标体系" aria-label="Permalink to &quot;2.1 三层监控指标体系&quot;">​</a></h3><p>传统监控只关注基础资源层（CPU、内存、磁盘、网络），但数据库运维还需要服务层和业务层的指标。一个完善的分片监控体系应覆盖以下三层：</p><p><strong>（1）基础设施层</strong> 采集每个物理节点和容器的资源使用情况，按分片维度聚合，快速定位资源瓶颈节点。核心指标包括CPU使用率、内存使用率、磁盘空间与I/O、网络带宽与延迟。</p><p><strong>（2）数据库引擎层</strong> 采集存储引擎的内部状态，包括缓冲池命中率、日志刷盘频率、锁等待分布、事务回滚率等专业指标。</p><p><strong>（3）业务语义层</strong> 将技术指标映射到业务视角，例如“订单创建事务P99延迟”“库存扣减失败率”“用户查询超时次数”。三层指标通过统一时间戳关联，为根因分析提供结构化数据基础。</p><h3 id="_2-2-监控维度" tabindex="-1">2.2 监控维度 <a class="header-anchor" href="#_2-2-监控维度" aria-label="Permalink to &quot;2.2 监控维度&quot;">​</a></h3><p>从监控对象来看，分片监控需要覆盖：</p><table tabindex="0"><thead><tr><th>监控维度</th><th>监控内容</th></tr></thead><tbody><tr><td><strong>节点级监控</strong></td><td>各分片节点的CPU、内存、磁盘I/O、网络带宽</td></tr><tr><td><strong>中间件级监控</strong></td><td>ShardingSphere/MyCat的QPS、连接数、线程池、路由效率</td></tr><tr><td><strong>集群级监控</strong></td><td>分片间数据均衡度、节点通信延迟、数据同步状态</td></tr><tr><td><strong>SQL级监控</strong></td><td>查询响应时间、慢查询日志、SQL执行次数、读写比例</td></tr><tr><td><strong>业务级监控</strong></td><td>事务成功率、吞吐量（QPS/TPS）、锁等待时间</td></tr></tbody></table><h2 id="三、核心监控指标详解" tabindex="-1">三、核心监控指标详解 <a class="header-anchor" href="#三、核心监控指标详解" aria-label="Permalink to &quot;三、核心监控指标详解&quot;">​</a></h2><h3 id="_3-1-sql执行相关指标" tabindex="-1">3.1 SQL执行相关指标 <a class="header-anchor" href="#_3-1-sql执行相关指标" aria-label="Permalink to &quot;3.1 SQL执行相关指标&quot;">​</a></h3><p>这是最核心的监控数据，直接反映了分片中间件的运行状态：</p><table tabindex="0"><thead><tr><th>指标名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>request_total</code></td><td>Counter</td><td>SQL请求总数，用于计算QPS</td></tr><tr><td><code>sql_statement_count</code></td><td>Counter</td><td>按类型（SELECT/UPDATE/INSERT/DELETE等）分类的SQL计数</td></tr><tr><td><code>parsed_sql_total</code></td><td>Counter</td><td>按SQL类型分类的解析总数</td></tr><tr><td><code>routed_sql_total</code></td><td>Counter</td><td>按类型分类的路由总数</td></tr><tr><td><code>jdbc_statement_execute_total</code></td><td>Counter</td><td>语句执行总数</td></tr><tr><td><code>jdbc_statement_execute_errors_total</code></td><td>Counter</td><td>语句执行错误总数</td></tr><tr><td><code>jdbc_statement_execute_latency_millis</code></td><td>Histogram</td><td>语句执行耗时分布</td></tr></tbody></table><h3 id="_3-2-路由与分片相关指标" tabindex="-1">3.2 路由与分片相关指标 <a class="header-anchor" href="#_3-2-路由与分片相关指标" aria-label="Permalink to &quot;3.2 路由与分片相关指标&quot;">​</a></h3><p>分片路由的健康状况直接影响查询效率：</p><table tabindex="0"><thead><tr><th>指标名称</th><th>说明</th></tr></thead><tbody><tr><td><code>routed_data_sources</code></td><td>每条SQL被路由到的数据源数量</td></tr><tr><td><code>routed_tables</code></td><td>每条SQL被路由到的表数量</td></tr><tr><td><code>sharding_datasource</code></td><td>执行SQL语句命中的分库</td></tr><tr><td><code>sharding_table</code></td><td>执行SQL语句命中的分表</td></tr></tbody></table><p><strong>关键观察点</strong>：如果一个查询路由到了大量节点，可能意味着广播查询或缺少分片键，是<strong>需要优化的危险信号</strong>。</p><h3 id="_3-3-连接池与事务指标" tabindex="-1">3.3 连接池与事务指标 <a class="header-anchor" href="#_3-3-连接池与事务指标" aria-label="Permalink to &quot;3.3 连接池与事务指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标名称</th><th>说明</th></tr></thead><tbody><tr><td><code>channel_count</code></td><td>ShardingSphere-Proxy的连接数</td></tr><tr><td><code>active_connections</code></td><td>活跃连接数</td></tr><tr><td><code>connection_acquire_latency</code></td><td>获取连接的延迟，连接池瓶颈的重要指标</td></tr><tr><td><code>jdbc_transactions_total</code></td><td>事务总数，按commit/rollback分类</td></tr><tr><td><code>transaction_commit_latency</code></td><td>事务提交延迟</td></tr></tbody></table><h3 id="_3-4-数据分布均衡指标" tabindex="-1">3.4 数据分布均衡指标 <a class="header-anchor" href="#_3-4-数据分布均衡指标" aria-label="Permalink to &quot;3.4 数据分布均衡指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标名称</th><th>说明</th></tr></thead><tbody><tr><td><strong>各分片数据量</strong></td><td>每个分片的数据行数/存储大小</td></tr><tr><td><strong>各分片QPS</strong></td><td>每个分片的查询请求量</td></tr><tr><td><strong>分片均衡度</strong></td><td>最大分片与最小分片的数据量比值</td></tr><tr><td><strong>热点行冲突率</strong></td><td>同一行数据被并发争抢的频率</td></tr></tbody></table><h3 id="_3-5-健康状态指标" tabindex="-1">3.5 健康状态指标 <a class="header-anchor" href="#_3-5-健康状态指标" aria-label="Permalink to &quot;3.5 健康状态指标&quot;">​</a></h3><p>在分布式数据库（如Elasticsearch）中，分片健康状态分为三种：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><strong>green（健康）</strong></td><td>所有主分片和副本分片均正常工作</td></tr><tr><td><strong>yellow（告警）</strong></td><td>有索引的分片数据不可用，但由于冗余配置，索引数据仍能访问</td></tr><tr><td><strong>red（异常）</strong></td><td>主分片数据和副本分片数据都不可用，部分数据不可访问</td></tr></tbody></table><h2 id="四、主流中间件的分片监控实践" tabindex="-1">四、主流中间件的分片监控实践 <a class="header-anchor" href="#四、主流中间件的分片监控实践" aria-label="Permalink to &quot;四、主流中间件的分片监控实践&quot;">​</a></h2><h3 id="_4-1-apache-shardingsphere" tabindex="-1">4.1 Apache ShardingSphere <a class="header-anchor" href="#_4-1-apache-shardingsphere" aria-label="Permalink to &quot;4.1 Apache ShardingSphere&quot;">​</a></h3><p>ShardingSphere 提供了完整的可观测性（Observability）方案，包含 Metrics 和 Tracing 两大模块。</p><h4 id="_4-1-1-metrics-指标监控" tabindex="-1">4.1.1 Metrics 指标监控 <a class="header-anchor" href="#_4-1-1-metrics-指标监控" aria-label="Permalink to &quot;4.1.1 Metrics 指标监控&quot;">​</a></h4><p>ShardingSphere 遵循 Metrics 标准，定义了一套可插拔的 SPI 标准。它不负责存储和展现 Metrics 信息，只负责在程序中进行埋点。</p><p><strong>默认支持 Prometheus</strong>：服务端通过 HTTP 协议定时抓取 Metrics 数据。</p><p><strong>支持的指标类型</strong>：</p><ul><li><strong>Counter（计数器）</strong> ：单调递增的累积度量（如请求总数）</li><li><strong>Gauge（仪表盘）</strong> ：可任意上下浮动的数值（如当前连接数）</li><li><strong>Histogram（直方图）</strong> ：对观测结果采样并按可配置桶计数（如请求延迟分布）</li><li><strong>Summary（摘要）</strong> ：计算滑动时间窗口上的可配置分位数</li></ul><p><strong>配置方式</strong>（ShardingSphere-Proxy）：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_17hn0y">metrics</span><span class="__shiki_140thh">:</span></span>
<span class="line"><span class="__shiki_17hn0y">  name</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">prometheus</span><span class="__shiki_21nrsd">  # 指定类型为prometheus</span></span></code></pre></div><h4 id="_4-1-2-tracing-链路追踪" tabindex="-1">4.1.2 Tracing 链路追踪 <a class="header-anchor" href="#_4-1-2-tracing-链路追踪" aria-label="Permalink to &quot;4.1.2 Tracing 链路追踪&quot;">​</a></h4><p>Tracing 插件用于获取 SQL 解析与 SQL 执行的链路跟踪信息。ShardingSphere 默认支持将追踪数据导出到 Jaeger 和 Zipkin。通过 SkyWalking 插件，可以实时监控 ShardingSphere 的各项性能指标，如 SQL 执行时间、分片策略执行效率等。</p><h4 id="_4-1-3-关键监控问题" tabindex="-1">4.1.3 关键监控问题 <a class="header-anchor" href="#_4-1-3-关键监控问题" aria-label="Permalink to &quot;4.1.3 关键监控问题&quot;">​</a></h4><p>通过监控可以回答的核心问题：</p><ul><li>当前系统的 QPS/TPS 是多少？</li><li>哪个业务的分片表访问最频繁？</li><li>平均 SQL 执行时间是多少？是否存在慢查询？</li><li>数据库集群的负载是否均衡？</li><li>当前容量下，何时需要增加新的分片？</li></ul><h3 id="_4-2-mycat" tabindex="-1">4.2 MyCat <a class="header-anchor" href="#_4-2-mycat" aria-label="Permalink to &quot;4.2 MyCat&quot;">​</a></h3><p>MyCat 提供了管理端口和可视化监控平台两套监控体系。</p><h4 id="_4-2-1-管理端口-9066" tabindex="-1">4.2.1 管理端口（9066） <a class="header-anchor" href="#_4-2-1-管理端口-9066" aria-label="Permalink to &quot;4.2.1 管理端口（9066）&quot;">​</a></h4><p>MyCat 默认开通两个端口：</p><ul><li><strong>8066</strong>：数据访问端口，用于 DML 和 DDL 操作</li><li><strong>9066</strong>：数据库管理端口，用于管理 MyCat 的整个集群状态</li></ul><p>连接管理控制台：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">mysql</span><span class="__shiki_dzsirb"> -h</span><span class="__shiki_dzsirb"> 192.168.200.210</span><span class="__shiki_dzsirb"> -p</span><span class="__shiki_dzsirb"> 9066</span><span class="__shiki_dzsirb"> -uroot</span><span class="__shiki_dzsirb"> -p123456</span></span></code></pre></div><p>管理命令包括 <code>show @@directmemory</code> 等内存监控命令。</p><h4 id="_4-2-2-mycat-web-mycat-eye" tabindex="-1">4.2.2 MyCat-Web（MyCat-eye） <a class="header-anchor" href="#_4-2-2-mycat-web-mycat-eye" aria-label="Permalink to &quot;4.2.2 MyCat-Web（MyCat-eye）&quot;">​</a></h4><p>MyCat-Web 是 MyCat 可视化运维的管理和监控平台，弥补了 MyCat 在监控上的空白。</p><p><strong>核心功能</strong>：</p><ul><li>管理和监控 MyCat 的流量、连接、活动线程和内存</li><li>统计 SQL 并分析<strong>慢 SQL</strong> 和<strong>高频 SQL</strong></li><li>IP 白名单和邮件告警模块</li><li>通过 JDBC 连接对 MyCat 和 MySQL 进行监控</li><li>监控远程服务器（Linux）的 CPU、内存、网络、磁盘</li></ul><p><strong>依赖</strong>：MyCat-Web 运行过程中需要依赖 ZooKeeper 作为配置中心，可以管理多个节点。</p><h3 id="_4-3-mongodb-分片监控" tabindex="-1">4.3 MongoDB 分片监控 <a class="header-anchor" href="#_4-3-mongodb-分片监控" aria-label="Permalink to &quot;4.3 MongoDB 分片监控&quot;">​</a></h3><p>MongoDB 分片集群的监控需要关注三个组件：</p><table tabindex="0"><thead><tr><th>组件</th><th>监控重点</th></tr></thead><tbody><tr><td><strong>mongos（路由节点）</strong></td><td>请求路由效率、连接数</td></tr><tr><td><strong>config server（配置服务器）</strong></td><td>元数据一致性、集群拓扑</td></tr><tr><td><strong>mongod（数据节点）</strong></td><td>存储、查询性能、副本集同步</td></tr></tbody></table><p><strong>关键监控命令</strong>：</p><ul><li><code>sh.status()</code>：检查数据分片均匀性</li><li><code>replSetGetStatus</code>：查看副本集主从同步进度（optimes字段）</li><li>聚合查询 <code>db.chunks</code> 集合：分析分片键分布</li></ul><p><strong>分片均衡器（Balancer）监控</strong>：Balancer 会监控各个 Shard 节点上的 Chunk 数量，当某个节点上的 Chunk 数量达到迁移阈值时触发迁移。</p><h3 id="_4-4-tidb-监控" tabindex="-1">4.4 TiDB 监控 <a class="header-anchor" href="#_4-4-tidb-监控" aria-label="Permalink to &quot;4.4 TiDB 监控&quot;">​</a></h3><p>TiDB 原生集成 Prometheus 和 Grafana，提供开箱即用的监控面板。</p><p><strong>关键监控项</strong>：</p><ul><li><strong>PD调度延迟</strong>：<code>pd_scheduler_queue_length</code> 反映调度队列积压情况</li><li><strong>TiKV存储引擎负载</strong>：<code>tikv_raftstore_append_log_duration_seconds</code> 衡量日志追加耗时</li><li><strong>慢查询监控</strong>：通过 <code>information_schema.slow_query</code> 表捕获超时SQL</li></ul><h2 id="五、数据倾斜与热点检测" tabindex="-1">五、数据倾斜与热点检测 <a class="header-anchor" href="#五、数据倾斜与热点检测" aria-label="Permalink to &quot;五、数据倾斜与热点检测&quot;">​</a></h2><h3 id="_5-1-什么是数据倾斜" tabindex="-1">5.1 什么是数据倾斜 <a class="header-anchor" href="#_5-1-什么是数据倾斜" aria-label="Permalink to &quot;5.1 什么是数据倾斜&quot;">​</a></h3><p><strong>数据倾斜</strong>是指大多数据分片节点的性能指标较低，而个别节点的性能指标（如内存、CPU、QPS）显著高于其他节点的情况。</p><p>在分布式系统中，数据通常按哈希或范围分片分布于多个节点。若分片键选择不当（如使用低基数字段），大量数据可能被分配到同一个分片，形成<strong>热点</strong>。</p><h3 id="_5-2-如何检测数据倾斜" tabindex="-1">5.2 如何检测数据倾斜 <a class="header-anchor" href="#_5-2-如何检测数据倾斜" aria-label="Permalink to &quot;5.2 如何检测数据倾斜&quot;">​</a></h3><p><strong>判断标准</strong>：通常情况下，若某数据分片节点的性能指标高出其他节点20%及以上，即可认为已产生数据倾斜，差值越大问题越严重。</p><p><strong>检测方法</strong>：</p><ol><li>查看各数据分片节点的内存/CPU使用率是否均衡</li><li>检查各分片的Key总数是否均衡</li><li>若Key数量均衡但资源使用不均衡，则可能存在<strong>大Key</strong></li><li>使用离线全量Key分析功能快速找出大Key</li></ol><h3 id="_5-3-热点分片自动检测" tabindex="-1">5.3 热点分片自动检测 <a class="header-anchor" href="#_5-3-热点分片自动检测" aria-label="Permalink to &quot;5.3 热点分片自动检测&quot;">​</a></h3><p>在支持热点检测的系统中（如Pegasus），Collector会自动向热点分片发送热点流量查询请求，统计异常的热点流量，并将结果上报到监控平台。</p><p><strong>最佳实践</strong>：系统应实时监控各分片的查询频率与数据量，当某分片QPS连续超过阈值时，自动触发分片拆分或数据迁移。</p><h2 id="六、分片重平衡的监控" tabindex="-1">六、分片重平衡的监控 <a class="header-anchor" href="#六、分片重平衡的监控" aria-label="Permalink to &quot;六、分片重平衡的监控&quot;">​</a></h2><h3 id="_6-1-为什么需要监控重平衡" tabindex="-1">6.1 为什么需要监控重平衡 <a class="header-anchor" href="#_6-1-为什么需要监控重平衡" aria-label="Permalink to &quot;6.1 为什么需要监控重平衡&quot;">​</a></h3><p>分片重平衡（Rebalancing）是数据迁移操作，涉及大量数据的网络传输和磁盘读写。如果监控不到位，可能引发：</p><ul><li>迁移任务阻塞，导致集群长期处于不一致状态</li><li>网络带宽被占满，影响正常业务</li><li>迁移失败但无告警，数据丢失风险</li></ul><h3 id="_6-2-重平衡监控的关键指标" tabindex="-1">6.2 重平衡监控的关键指标 <a class="header-anchor" href="#_6-2-重平衡监控的关键指标" aria-label="Permalink to &quot;6.2 重平衡监控的关键指标&quot;">​</a></h3><p><strong>（1）均衡器（Balancer）状态</strong> 数据迁移完全依赖均衡器完成。如果均衡器未开启，待迁移分片上的数据将无法迁出。</p><p><strong>（2）迁移进度</strong> 监控系统应显示：</p><ul><li>已移入/移出的分片数量（如“已移入6个，共24个”）</li><li>每个表的受影响分片计数和数据大小</li><li>再平衡状态（进行中/已完成/失败）</li></ul><p><strong>（3）迁移性能</strong></p><ul><li>迁移速率（MB/s）</li><li>迁移对业务QPS的影响程度</li></ul><h3 id="_6-3-mongodb-重平衡监控" tabindex="-1">6.3 MongoDB 重平衡监控 <a class="header-anchor" href="#_6-3-mongodb-重平衡监控" aria-label="Permalink to &quot;6.3 MongoDB 重平衡监控&quot;">​</a></h3><p>在 MongoDB 中，可以通过以下方式监控重平衡：</p><ul><li><code>balancerCollectionStatus</code> 命令查看碎片整理状态和剩余数据段数量</li><li>获取 Balancer 的运行结果（成功和失败数量的统计）</li><li>查看待迁移分片表的 Chunk 信息</li></ul><h2 id="七、告警与故障处理" tabindex="-1">七、告警与故障处理 <a class="header-anchor" href="#七、告警与故障处理" aria-label="Permalink to &quot;七、告警与故障处理&quot;">​</a></h2><h3 id="_7-1-告警策略设计" tabindex="-1">7.1 告警策略设计 <a class="header-anchor" href="#_7-1-告警策略设计" aria-label="Permalink to &quot;7.1 告警策略设计&quot;">​</a></h3><p><strong>（1）阈值告警</strong> 设置阈值报警，当某个指标超过预设阈值时触发报警通知（邮件、短信、电话等）。</p><p><strong>常见告警阈值示例</strong>：</p><table tabindex="0"><thead><tr><th>指标</th><th>建议阈值</th><th>说明</th></tr></thead><tbody><tr><td>分片CPU使用率</td><td>&gt; 80%</td><td>可能需扩容或迁移</td></tr><tr><td>分片磁盘使用率</td><td>&gt; 85%</td><td>预警，&gt;95%为紧急</td></tr><tr><td>分片间数据量偏差</td><td>&gt; 20%</td><td>存在数据倾斜</td></tr><tr><td>慢查询数量</td><td>超过基线3倍</td><td>可能存在SQL问题</td></tr><tr><td>连接池使用率</td><td>&gt; 90%</td><td>连接数不足</td></tr></tbody></table><p><strong>（2）动态基线告警</strong> 固定阈值告警在动态负载下容易产生大量误报。动态基线异常检测让系统学习每个指标在一天内不同时段的历史分布（区分工作日和周末），建立动态的正常波动范围。</p><p>例如，某分片的QPS在早高峰从5000升至8000是正常现象，只有升至12000且伴随错误率上升时才被判定为异常。</p><p><strong>（3）多指标联合检测</strong> 单一指标异常可能是噪声，但CPU、锁等待、慢查询三个指标同时上升则大概率存在真实问题。</p><p><strong>（4）告警聚合与降噪</strong> 告警风暴发生时，将同一根因引发的多个关联告警合并为一条“根因告警”。例如，某分片所在物理机磁盘延迟升高，导致慢查询、连接超时、事务回滚等多条告警被聚合为一条“存储层性能劣化”告警。</p><h3 id="_7-2-故障排查路径" tabindex="-1">7.2 故障排查路径 <a class="header-anchor" href="#_7-2-故障排查路径" aria-label="Permalink to &quot;7.2 故障排查路径&quot;">​</a></h3><p><strong>典型故障排查思路</strong>：</p><ol><li><strong>确认故障范围</strong>：是个别分片还是全局问题？</li><li><strong>检查资源层</strong>：CPU、内存、磁盘、网络是否有异常</li><li><strong>检查分片层</strong>：是否有分片数据倾斜、热点</li><li><strong>检查SQL层</strong>：是否有慢查询、全表广播</li><li><strong>检查中间件层</strong>：连接池、线程池是否耗尽</li><li><strong>链路追踪</strong>：通过Tracing定位具体慢在哪个环节</li></ol><h3 id="_7-3-自动化故障处理" tabindex="-1">7.3 自动化故障处理 <a class="header-anchor" href="#_7-3-自动化故障处理" aria-label="Permalink to &quot;7.3 自动化故障处理&quot;">​</a></h3><p>利用监控工具的告警联动功能，可以实现：</p><ul><li>自动切换故障节点</li><li>自动重启服务</li><li>自动触发分片重平衡或流量重定向</li></ul><h2 id="八、最佳实践总结" tabindex="-1">八、最佳实践总结 <a class="header-anchor" href="#八、最佳实践总结" aria-label="Permalink to &quot;八、最佳实践总结&quot;">​</a></h2><h3 id="_8-1-监控体系建设原则" tabindex="-1">8.1 监控体系建设原则 <a class="header-anchor" href="#_8-1-监控体系建设原则" aria-label="Permalink to &quot;8.1 监控体系建设原则&quot;">​</a></h3><ol><li><strong>三层指标全覆盖</strong>：基础设施层 + 数据库引擎层 + 业务语义层</li><li><strong>指标可关联运维动作</strong>：每一个监控项都必须可关联到具体的运维动作</li><li><strong>告警需降噪</strong>：避免告警风暴，使用动态基线和告警聚合</li><li><strong>监控需自动发现</strong>：分布式节点动态扩缩容时，监控系统需自动识别新节点</li></ol><h3 id="_8-2-分片监控的必备清单" tabindex="-1">8.2 分片监控的必备清单 <a class="header-anchor" href="#_8-2-分片监控的必备清单" aria-label="Permalink to &quot;8.2 分片监控的必备清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>必须监控的指标</th></tr></thead><tbody><tr><td><strong>资源</strong></td><td>各分片CPU、内存、磁盘、网络</td></tr><tr><td><strong>性能</strong></td><td>QPS/TPS、平均响应时间、P95/P99延迟</td></tr><tr><td><strong>路由</strong></td><td>路由到各分片的SQL数量、广播查询比例</td></tr><tr><td><strong>数据分布</strong></td><td>各分片数据量、分片均衡度、热点分片</td></tr><tr><td><strong>SQL</strong></td><td>慢查询排行榜、SQL类型分布、错误率</td></tr><tr><td><strong>连接</strong></td><td>活跃连接数、连接获取延迟、连接池使用率</td></tr><tr><td><strong>事务</strong></td><td>事务吞吐量、提交/回滚率、分布式事务延迟</td></tr></tbody></table><h3 id="_8-3-监控工具选型建议" tabindex="-1">8.3 监控工具选型建议 <a class="header-anchor" href="#_8-3-监控工具选型建议" aria-label="Permalink to &quot;8.3 监控工具选型建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具组合</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Prometheus + Grafana</strong></td><td>最通用的组合，ShardingSphere/TiDB原生支持</td></tr><tr><td><strong>ELK Stack</strong></td><td>日志集中管理和慢查询分析</td></tr><tr><td><strong>Jaeger/Zipkin</strong></td><td>SQL链路追踪和分布式事务诊断</td></tr><tr><td><strong>MyCat-Web</strong></td><td>MyCat专用可视化监控平台</td></tr><tr><td><strong>云厂商监控</strong></td><td>天翼云、阿里云等提供的分片集群监控面板</td></tr></tbody></table><h3 id="_8-4-核心启示" tabindex="-1">8.4 核心启示 <a class="header-anchor" href="#_8-4-核心启示" aria-label="Permalink to &quot;8.4 核心启示&quot;">​</a></h3><p>分片监控不是简单的指标堆砌，而是围绕“<strong>运维价值链路</strong>”重新定义数据采集、分析和行动的逻辑。最终目标是让运维团队从“<strong>全天候盯屏</strong>”升级为“<strong>策略定义者</strong>”——系统承担重复性的感知和处置工作，工程师专注于规则优化和架构演进。</p><p><strong>没有监控的分片管理，等同于盲人摸象。</strong> 只有建立了完善的监控体系，才能真正驾驭分库分表架构的复杂性，做到问题早发现、故障快恢复、容量可预期。</p><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>分片监控是分片管理中<strong>最基础也最重要</strong>的环节。理解分片监控需要把握以下要点：</p><ol><li><strong>核心价值</strong>：保障可用性、定位性能瓶颈、支撑容量规划</li><li><strong>三层指标</strong>：基础设施层 → 数据库引擎层 → 业务语义层，层层递进</li><li><strong>监控维度</strong>：节点级、中间件级、集群级、SQL级、业务级全覆盖</li><li><strong>关键指标</strong>：SQL执行、路由效率、连接池、数据均衡、健康状态</li><li><strong>主流实现</strong>：ShardingSphere（Metrics+Tracing）、MyCat（管理端口+MyCat-Web）、MongoDB（sh.status()+Balancer监控）、TiDB（Prometheus原生集成）</li><li><strong>数据倾斜检测</strong>：关注分片间资源使用率偏差（&gt;20%即告警），定位大Key和热点分片</li><li><strong>告警策略</strong>：阈值告警 + 动态基线 + 多指标联合检测 + 告警聚合降噪</li><li><strong>最佳实践</strong>：三层指标全覆盖、告警可降噪、监控可自动发现、指标可关联运维动作</li></ol>`,123)])])}const b=a(d,[["render",n]]);export{p as __pageData,b as default};
